const commit="f7249293ad84805b0b690be3035d14bfd5d594fe";
const rel="problems/linalg/cholesky_py/submission.py";
const mk=await tools.exec_command({
  cmd:`set -euo pipefail
commit=${commit}
rel=${rel}
git cat-file -e "$commit:$rel"
resolved_commit="$(git rev-parse "$commit^{commit}")"
expected_blob="$(git rev-parse "$commit:$rel")"
expected_sha256="$(git show "$commit:$rel" | sha256sum | awk '{print $1}')"
wt="$(mktemp -d /tmp/gpumode-submit-f7249293-XXXXXX)"
rmdir "$wt"
git worktree add --detach "$wt" "$commit"
actual_head="$(git -C "$wt" rev-parse HEAD)"
actual_blob="$(git -C "$wt" hash-object "$rel")"
actual_sha256="$(sha256sum "$wt/$rel" | awk '{print $1}')"
test "$resolved_commit" = "$commit"
test "$actual_head" = "$commit"
test "$actual_blob" = "$expected_blob"
test "$actual_sha256" = "$expected_sha256"
test -z "$(git -C "$wt" status --porcelain)"
printf 'WORKTREE=%s\\nCOMMIT=%s\\nPATH=%s\\nEXPECTED_BLOB=%s\\nACTUAL_BLOB=%s\\nEXPECTED_SHA256=%s\\nACTUAL_SHA256=%s\\nSTATUS=verified-clean-detached\\n' "$wt" "$actual_head" "$rel" "$expected_blob" "$actual_blob" "$expected_sha256" "$actual_sha256"`,
  workdir:"/home/ubuntu/gpumode",yield_time_ms:10000,max_output_tokens:20000
});
const m=mk.output.match(/WORKTREE=(.+)/);
if(!m) throw new Error("worktree path missing");
store("submit_wt",m[1].trim());
store("commit",commit);
store("rel",rel);
store("verification_output",mk.output);
text(mk.output);

